40	    private ResourceAccessor resolveResourceAccessor() throws FileNotFoundException {
41	
42	        CompositeResourceAccessor compositeResourceAccessor = new CompositeResourceAccessor();
43	        compositeResourceAccessor
44	                .addResourceAccessor(new ClassLoaderResourceAccessor(Thread.currentThread().getContextClassLoader()));
45	
46	        if (!config.changeLog.startsWith("filesystem:") && config.searchPath.isEmpty()) {
47	            return compositeResourceAccessor;
48	        }
49	
50	        if (config.searchPath.isEmpty()) {
51	            compositeResourceAccessor.addResourceAccessor(
52	                    new DirectoryResourceAccessor(
53	                            Paths.get(StringUtil.changePrefix(config.changeLog, "filesystem:", "")).getParent()));
54	            return compositeResourceAccessor;
55	        }
56	
57	        for (String searchPath : config.searchPath.get()) {
58	            compositeResourceAccessor.addResourceAccessor(new DirectoryResourceAccessor(Paths.get(searchPath)));
59	        }
60	
61	        return compositeResourceAccessor;
62	    }
