64	    private String parseChangeLog(String changeLog) {
65	
66	        if (changeLog.startsWith("filesystem:") && config.searchPath.isEmpty()) {
67	            return Paths.get(StringUtil.changePrefix(changeLog, "filesystem:", "")).getFileName().toString();
68	        }
69	
70	        if (changeLog.startsWith("filesystem:")) {
71	            return StringUtil.changePrefix(changeLog, "filesystem:", "");
72	        }
73	
74	        if (changeLog.startsWith("classpath:")) {
75	            return StringUtil.changePrefix(changeLog, "classpath:", "");
76	        }
77	
78	        return changeLog;
79	    }
