89	                String jdbcUrl = agroalDataSource.getConfiguration().connectionPoolConfiguration()
90	                        .connectionFactoryConfiguration().jdbcUrl();
91	                Connection connection = DriverManager.getConnection(jdbcUrl, config.username.get(), config.password.get());
92	
93	                database = DatabaseFactory.getInstance()
94	                        .findCorrectDatabaseImplementation(
95	                                new JdbcConnection(connection));
96	
97	            } else {
98	                database = DatabaseFactory.getInstance()
99	                        .findCorrectDatabaseImplementation(new JdbcConnection(dataSource.getConnection()));
100	            }
101	
102	            if (database != null) {
103	                database.setDatabaseChangeLogLockTableName(config.databaseChangeLogLockTableName);
104	                database.setDatabaseChangeLogTableName(config.databaseChangeLogTableName);
105	                config.liquibaseCatalogName.ifPresent(database::setLiquibaseCatalogName);
106	                config.liquibaseSchemaName.ifPresent(database::setLiquibaseSchemaName);
107	                config.liquibaseTablespaceName.ifPresent(database::setLiquibaseTablespaceName);
108	
109	                if (config.defaultCatalogName.isPresent()) {
110	                    database.setDefaultCatalogName(config.defaultCatalogName.get());
111	                }
112	                if (config.defaultSchemaName.isPresent()) {
113	                    database.setDefaultSchemaName(config.defaultSchemaName.get());
114	                }
115	            }
