54	    public void doStartActions(String dataSourceName) {
55	        if (!config.getValue().enabled) {
56	            return;
57	        }
58	        // Liquibase is active when the datasource itself is active.
59	        if (!Arc.container().instance(DataSources.class).get().getActiveDataSourceNames().contains(dataSourceName)) {
60	            return;
61	        }
62	
63	        InstanceHandle<LiquibaseFactory> liquibaseFactoryHandle = LiquibaseFactoryUtil.getLiquibaseFactory(dataSourceName);
64	        try {
65	            LiquibaseFactory liquibaseFactory = liquibaseFactoryHandle.get();
66	            var config = liquibaseFactory.getConfiguration();
67	            if (!config.cleanAtStart && !config.migrateAtStart) {
68	                return;
69	            }
70	            try (Liquibase liquibase = liquibaseFactory.createLiquibase();
71	                    ResettableSystemProperties resettableSystemProperties = liquibaseFactory
72	                            .createResettableSystemProperties()) {
73	                if (config.cleanAtStart) {
74	                    liquibase.dropAll();
75	                }
76	                if (config.migrateAtStart) {
77	                    var lockService = LockServiceFactory.getInstance()
78	                            .getLockService(liquibase.getDatabase());
79	                    lockService.waitForLock();
80	                    try {
81	                        if (config.validateOnMigrate) {
82	                            liquibase.validate();
83	                        }
84	                        liquibase.update(liquibaseFactory.createContexts(), liquibaseFactory.createLabels());
85	                    } finally {
86	                        lockService.releaseLock();
